import json
from pathlib import Path
p=Path('/workspace/sites/olympiad-atlas'); new=[]
def add(y,n,r,t,tags,s,reason,solution=None):
 url=f'https://web.evanchen.cc/exams/USAMO-{y}-notes.pdf'
 new.append(dict(id=f'us-usamo-{y}-{n}',country='United States',competition='USAMO',year=y,number=str(n),statement=s,solution=solution or f'[View Evan Chen’s worked solution notes]({url}).',sourceUrl=url,solutionUrl=url,solutionKind='original-exposition' if solution else 'source-link',topic=t,tags=tags.split('|'),difficulty=r,ratingReason=reason,reviewStatus='individually-assessed',notes='Statement restated in original wording; mathematical argument individually checked. Linked author-maintained notes are not labelled official.'))
add(2018,2,7,'Algebra','Functional equations|Jensen equation|Boundedness|Substitution',r'Find all functions $f:(0,\infty)\to(0,\infty)$ such that $\displaystyle f\left(x+\frac1y\right)+f\left(y+\frac1z\right)+f\left(z+\frac1x\right)=1$ whenever $x,y,z>0$ and $xyz=1$.','Two changes of variables turn the product condition into an additive condition on three arguments. One then obtains Jensen’s equation on a restricted interval. Positivity supplies the boundedness needed to prove linearity; handling the interval and recovering the full domain are essential, not assumed continuity.')
add(2017,6,5.5,'Algebra','Inequalities|Supporting lines|Factorisation|Equality cases',r'For nonnegative real numbers $a,b,c,d$ with $a+b+c+d=4$, determine the minimum of $\displaystyle\frac a{b^3+4}+\frac b{c^3+4}+\frac c{d^3+4}+\frac d{a^3+4}$.','The minimum occurs at a boundary configuration rather than four equal variables. Finding a linear lower bound that preserves this equality is the main insight. Its validity reduces to a factorisation, and the remaining cyclic cross terms combine into a product bounded by AM–GM.')
add(2016,2,5.5,'Number theory','Factorials|Prime valuations|Legendre formula|Residues',r'Prove that $\displaystyle (k^2)!\prod_{j=0}^{k-1}\frac{j!}{(j+k)!}$ is an integer for every positive integer $k$.','Legendre’s formula reduces integrality to one floor inequality for each prime power. The decisive observation is that the first k consecutive nonnegative residues have the smallest possible residue sum among intervals of length k. An integer-valued expression then absorbs the remaining fractional part.')
add(2016,5,7,'Geometry','Complex numbers|Incentre|Arc midpoints|Angle bisectors',r'Triangle $ABC$ contains an equilateral pentagon $AMNPQ$ whose vertices satisfy $M\in AB$, $Q\in AC$, and $N,P\in BC$. Put $S=MN\cap PQ$, and let $\ell$ bisect $\angle MSQ$. If $O$ and $I$ are the circumcentre and incentre of $ABC$, prove $OI\parallel\ell$.','On the circumcircle, the sum of the three opposite arc midpoints represents the incentre. Equal pentagon sides turn a quarter-turn of this sum into a telescoping sum of edge vectors. The final difference of equal-length vectors gives an angle bisector. Recognising and connecting these two geometric identities is the challenge.')
add(2016,6,6.5,'Combinatorics','Adversarial games|Information|Sliding windows|Pigeonhole principle',r'Fix integers $n\ge k\ge2$. A wizard places $2n$ face-down cards in a row, with exactly two cards bearing each label $1,\ldots,n$. On each move you select $k$ positions, and the wizard reveals their cards. You win if two revealed labels agree. Otherwise, after you have seen the revealed positions and labels, the wizard secretly permutes these $k$ cards and turns them face down. Determine the pairs $(n,k)$ for which a strategy guarantees a win within a bounded number of moves, whatever the initial order and the wizard’s choices.','Overlapping windows reveal the value of each card just left behind, eventually fixing more than n positions. The opposite case requires an indistinguishability argument: a freshly shuffled complete set of labels can always conceal the complementary labels needed to avoid a match. Both information gained and information lost must be handled carefully.')
add(2015,3,6.5,'Combinatorics','Subsets|Multiplicative functions|Support|Counting',r'For $S=\{1,\ldots,n\}$, colour every subset of $S$ red or blue. Let $f(T)$ count the blue subsets of $T$. How many such colourings satisfy $f(U)f(V)=f(U\cup V)f(U\cap V)$ for every $U,V\subseteq S$?','The positive support must be upward closed and closed under intersection, hence generated by one minimum set. Removing that set makes the empty set blue; the multiplicative identity then determines every value from singleton values. Recovering which sets are blue gives an interval of the subset lattice, whose endpoints can be counted.')
add(2015,5,6.5,'Number theory','Primality contradiction|Modular factorisation|Ordering',r'Let $a,b,c,d,e$ be pairwise distinct positive integers satisfying $a^4+b^4=c^4+d^4=e^5$. Prove that $ac+bd$ is composite.','Assuming ac+bd prime produces a modular factorisation involving e and a⁴−d⁴. Size bounds exclude the e factor and give ac+bd≤a²+d²; symmetry gives a second bound. The ordering forced by equal sums of fourth powers contradicts one of those two bounds. Several elementary steps must be coordinated.')
data=json.loads((p/'data/americas.json').read_text());ids={x['id'] for x in new};data=[x for x in data if x['id'] not in ids]+new
(p/'data/americas.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
c=json.loads((p/'research/americas-coverage.json').read_text());full={2019:[6.5,7,9,5.5,6,8.5],2018:[4.5,7,8,5.5,8,8],2017:[4.5,7.5,9,5.5,8,5.5],2016:[7,5.5,8.5,7,7,6.5],2015:[5.5,6.5,6.5,6,6.5,8]}
c['fullyScreened']=[x for x in c['fullyScreened'] if not(x['competition']=='USAMO' and x['year'] in full)]
c['partiallyScreened']=[x for x in c['partiallyScreened'] if not(x['competition']=='USAMO' and x['year'] in full)]
for year,ratings in full.items():c['fullyScreened'].append(dict(competition='USAMO',year=year,ratings=ratings,source=f'https://web.evanchen.cc/exams/USAMO-{year}-notes.pdf'))
c['papersScreened']=len(c['fullyScreened']);c['problemAppearancesScreened']=sum(len(x['ratings']) for x in c['fullyScreened']+c['partiallyScreened']);c['uniqueIncluded']=len(data)
c['gaps'][1]='US: USAJMO 2015–2026 and USAMO 2015–2025 fully screened. USAMO 2026 Q1 and Q3 remain unrated because source proofs are incomplete; Q2/Q4/Q5/Q6 assessed. Older complete and partial USAMO papers are enumerated below; other years remain pending.'
c.setdefault('verificationNotes',[]).append('USAMO 2018 Q6 is excluded above target: the concluding source bullets transpose the fantastic/non-fantastic categories, but the prior degree-parity argument gives the correct conclusion. USAMO 2019 Q3 is excluded above target; its displayed source proof implicitly assumes integer coefficients and omits a coefficient later, so that source is not treated as a verified complete proof for the stated real-coefficient problem. All included questions in these papers were checked separately. USAMO 2016 Q6 uses k<n, correcting the later source line saying k≤n; USAMO 2016 Q5 cyclic arc-midpoint names were checked against the geometry.')
(p/'research/americas-coverage.json').write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n');print('Total',len(data),'Full papers',len(c['fullyScreened']))
